INSERT INTO public."csr_areas" ("id","title","body","published","sort_order","created_at","updated_at") VALUES ('a6bf3daa-e164-4035-8719-dae2902d9f27','Livelihood & Women Empowerment','Vocational skill training for rural youth, supporting self-help groups (SHGs), and micro-enterprise development in project catchment communities.',true,'2','2026-11-03T03:31:37.17592+00:00','2026-11-03T03:31:37.17592+00:00');
INSERT INTO public."csr_areas" ("id","title","body","published","sort_order","created_at","updated_at") VALUES ('6282191b-1d6c-4916-a389-d27ea45274d9','Quality Education & Health','School infrastructure enhancement, drinking water filtration in village schools, sanitation facilities, and preventive healthcare camps.',true,'3','2026-11-03T03:31:37.17592+00:00','2026-11-03T03:31:37.17592+00:00');
