INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('861cf126-ee5a-466c-bf33-a8a32f2e3240','environmental','metric',NULL,'Environmental Compliance','100%','','',NULL,true,'5','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('663be892-809d-4977-bc05-52f4bcc57030','environmental','accordion',NULL,'Carbon Reduction','','We measure and manage emissions across every project lifecycle — from material sourcing to construction and operations. Energy-efficient equipment, optimized logistics and low-carbon materials have cut our carbon intensity by 40% against our baseline, with a clear roadmap toward deeper reductions.','',NULL,true,'6','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('392b1355-f20b-45b1-9ad2-a07a7edb900f','environmental','accordion',NULL,'Renewable Energy','','Our waste-to-energy and solar installations convert environmental liabilities into clean power. India''s largest waste-to-energy plant in Delhi, delivered by Ramky, processes municipal waste while feeding renewable electricity into the grid.','',NULL,true,'7','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('8a72c04f-3e16-431d-8283-2fb810c7400c','environmental','accordion',NULL,'Waste Management & Circularity','','From engineered landfills to material recovery and leachate treatment, our approach keeps resources in circulation. We design every water and waste project for maximum recovery, reuse and safe disposal — protecting groundwater, soil and communities.','',NULL,true,'8','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('3ec6afa3-0d8f-42b6-b478-6ef7779c3e0d','environmental','accordion',NULL,'Water Stewardship','','Water is central to our business and our responsibility. Our treatment plants return hundreds of millions of litres of safe water to the environment every day, and our project designs prioritize recycling and recharge.','',NULL,true,'9','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
