INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('9884c08a-d957-4498-b9d9-e1fbcdfd39aa','social','accordion',NULL,'Diversity & Inclusion','','We are building a workforce that reflects the communities we serve — expanding opportunities for women in engineering and site leadership, and ensuring fair, merit-based growth at every level of the organization.','',NULL,true,'17','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('b8436118-55d6-4e65-90a7-4b5dac5fe9eb','social','accordion',NULL,'Community Impact','','Our CSR programmes focus on education, healthcare, sanitation and skill development in the regions around our projects. We engage local communities early, hire locally where possible, and invest in infrastructure that outlasts construction.','',NULL,true,'18','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('819d9303-724d-4b58-8f45-b85bbc2a197c','social','accordion',NULL,'Employee Wellness & Safety','','Safety is a non-negotiable value, not a statistic. Every site operates under rigorous health and safety systems with continuous training, protective equipment and transparent incident reporting — because every person goes home safe, every day.','',NULL,true,'19','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('e2aa10b7-3fd2-43ca-b40a-0a94f3a7661e','social','accordion',NULL,'Skills & Livelihoods','','Through on-the-job training and partnerships with local institutions, we help workers build transferable skills that raise incomes long after a project is complete.','',NULL,true,'20','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
