INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('4b587dfa-24ba-4f26-8a07-2ed87f543aed','governance','accordion',NULL,'Corporate Ethics','','Our Code of Conduct applies to every employee, director and business partner. It covers anti-bribery and anti-corruption, fair competition, conflicts of interest and respectful workplace conduct — reinforced through mandatory training and leadership accountability.','',NULL,true,'8','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('ec1b9b3d-bd66-407e-8dcb-6cc9958ddad2','governance','accordion',NULL,'Board Oversight & Leadership Standards','','A majority-independent Board with dedicated audit, risk and stakeholder committees provides oversight of strategy, compliance and executive performance. Leadership is held to clear standards of integrity, disclosure and succession planning.','',NULL,true,'9','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('7d16b697-a9b1-4001-a923-d404e900e0b4','governance','accordion',NULL,'Data Privacy & Security','','We protect the data of employees, clients and partners through defined access controls, secure systems and compliance with applicable data protection regulations. Privacy is treated as a governance responsibility, not an IT afterthought.','',NULL,true,'10','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('37b5b554-6497-4f62-9f92-209dd3b66355','governance','accordion',NULL,'Whistleblower & Grievance Mechanisms','','Confidential channels allow anyone — employees, vendors or community members — to raise concerns without fear of retaliation. Every report is reviewed independently and tracked to resolution.','',NULL,true,'11','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
