INSERT INTO public."esg_items" ("id","page_slug","kind","group_title","title","value","body","year","url","published","sort_order","created_at","updated_at") VALUES ('340f298d-51b8-41be-98bb-8b0dc79ab65e','esg-reporting','accordion',NULL,'Our Reporting Approach','','We report with reference to the Global Reporting Initiative (GRI) Standards and the SASB framework for engineering and construction, alongside SEBI''s Business Responsibility and Sustainability Reporting (BRSR) requirements. Our disclosures cover environmental performance, workforce and community impact, and governance practices.','',NULL,true,'5','2026-11-03T01:27:11.014403+00:00','2026-11-03T01:27:11.014403+00:00');
