INSERT INTO public."home_sustainability" ("id","eyebrow","title","body","side_stats","video_url","poster_url","updated_at") VALUES ('1','Sustainability','Towards sustainable growth — not as a slogan, as a method.','Environmental stewardship is embedded in how we plan sites, manage material, treat water and hand assets over. We measure what we consume, reduce what we can, and design for the operating life ahead.','[{"l": "Water treated per day", "v": "1.8 M m³"}, {"l": "Certified systems", "v": "ISO 14001"}]'::jsonb,'asset:hummingbird','asset:hummingbird-poster','2026-11-03T09:54:12.154446+00:00');
