-- home_top: 1 rows
INSERT INTO public."home_top" ("id","about_eyebrow","about_title","about_paragraphs","about_highlights","about_images","journey_eyebrow","journey_title","updated_at") VALUES ('1','Who we are','An integrated developer of essential public infrastructure.','["Ramky Infrastructure Limited (Ramky Infra) is a flagship company of Ramky Group, one of the emerging leaders in the field of infrastructure development & environment management. Since the incorporation of its business in 1994, the Company has proudly completed a wide range of construction and infrastructure projects in various sectors such as water and wastewater, transportation (including terminals), irrigation, industrial construction (including SEZs & industrial parks), power transmission and distribution, buildings (including residential, commercial & retail property).", "With a highly skilled team of over 2000 people, headquartered in Hyderabad, Telangana, the Company manages its business operations in India and internationally. The pan-India presence has enabled the company to serve the growing infrastructure needs across the country. Ramky Infrastructure Ltd is a customer centric, environment concerned and development oriented company.", "Ramky Infra operates mainly in three principal business segments — the Construction Business & international business is operated directly by the Company and the Developer business is operated through its subsidiaries & associates.", "Employing the public-private partnership model, Ramky has successfully utilized its core strengths and competencies to fulfill the cutting edge client requirements. The International Business is operated by the Ramky Infrastructure which takes up activities of overseas business explorations in areas such as infrastructure development, roads, and water & waste water.", "Ramky Infra is ISO 9001:2015, ISO 14001:2015 and ISO 45001:2018 certified for Quality Management Systems, Environment Management System and Occupational Health & Safety Management Systems which the Company applies to the design, development, engineering, procurement and construction of projects."]'::jsonb,'[{"d": "Zero-harm site culture", "t": "Safety first"}, {"d": "Low-impact delivery", "t": "Sustainable"}, {"d": "Concept to O&M", "t": "Integrated"}]'::jsonb,'[{"alt": "Aerial view of a highway curving through dense forest", "url": "asset:who-main", "position": "50% 55%"}, {"alt": "Aerial view of the Nagole sewage treatment plant", "url": "asset:who-1", "position": "60% 50%"}, {"alt": "Aerial view of a residential housing project", "url": "asset:who-2", "position": "50% 40%"}]'::jsonb,'Our Journey','Three decades of building, milestone by milestone.','2026-11-04T07:10:47.046834+00:00');
