INSERT INTO public."landmark_projects" ("id","name","detail","image_url","fit","published","sort_order","created_at","updated_at") VALUES ('3a25b69a-41ed-4763-a582-831b5105bcbd','Srinagar to Banihal Section (NH-44)','Rehabilitation, Strengthening and Four-Lanning of Srinagar to Banihal Section (NH-44).','asset:lm1','cover',true,'1','2026-11-03T09:54:08.571848+00:00','2026-11-03T09:54:08.571848+00:00');
INSERT INTO public."landmark_projects" ("id","name","detail","image_url","fit","published","sort_order","created_at","updated_at") VALUES ('f40acc6e-8f80-473b-bbaf-7efc4b95b059','Jawahar Nagar Leachate Treatment Facility','A specialized waste-management plant located at the Jawahar Nagar municipal solid waste dump yard in Hyderabad, Telangana — a 2 MLD capacity system that utilizes advanced Mechanical Vapor Recompression (MVR) technology.','asset:lm2','cover',true,'2','2026-11-03T09:54:08.820837+00:00','2026-11-03T09:54:08.820837+00:00');
INSERT INTO public."landmark_projects" ("id","name","detail","image_url","fit","published","sort_order","created_at","updated_at") VALUES ('d9c95351-3d60-4cb2-9e77-6945c1476375','410 MLD Water Treatment Plant, Kodandapur','A massive infrastructure asset located in the Nalgonda district of Telangana. This plant plays into the state''s broader water initiatives like Mission Bhagiratha.','asset:lm3','cover',true,'3','2026-11-03T09:54:09.058468+00:00','2026-11-03T09:54:09.058468+00:00');
INSERT INTO public."landmark_projects" ("id","name","detail","image_url","fit","published","sort_order","created_at","updated_at") VALUES ('3e3f4873-3872-4be6-b408-e42a19c94510','Jawaharlal Nehru Pharma City (JNPC)','Located at Parawada near Visakhapatnam (Vizag), Andhra Pradesh. Spanning over 2,400 acres, JNPC is a highly specialized industrial park designed explicitly for the pharmaceutical sector.','asset:lm4','cover',true,'4','2026-11-03T09:54:09.296188+00:00','2026-11-03T09:54:09.296188+00:00');
INSERT INTO public."landmark_projects" ("id","name","detail","image_url","fit","published","sort_order","created_at","updated_at") VALUES ('522c81d7-f936-418c-a8da-0271ac182ad3','NAM Expressway','The NAM Expressway (Narketpally–Addanki–Medarametla Road) is a prominent 212.5-kilometer, four-lane highway that serves as a vital interstate corridor between Telangana and Andhra Pradesh.','asset:namExpresswayCombined','contain',true,'5','2026-11-03T09:54:09.53423+00:00','2026-11-03T09:54:09.53423+00:00');
INSERT INTO public."landmark_projects" ("id","name","detail","image_url","fit","published","sort_order","created_at","updated_at") VALUES ('8a81cf78-73c6-4c60-bd91-270420164c0d','Indian Institute of Foreign Trade (IIFT), Kolkata','An autonomous, premier public business school located in Madurdaha, West Bengal.','asset:lm7','cover',true,'6','2026-11-03T09:54:09.771998+00:00','2026-11-03T09:54:09.771998+00:00');
INSERT INTO public."landmark_projects" ("id","name","detail","image_url","fit","published","sort_order","created_at","updated_at") VALUES ('e3351e57-be59-44bb-98d3-c496685b001a','Musi River Rejuvenation Project','Development of five decentralised sewage treatment plants along the Musi River to treat wastewater and reduce untreated sewage discharge, 480 MLD Total Treatment Capacity','asset:musiCombined','contain',true,'7','2026-11-03T09:54:10.009899+00:00','2026-11-03T09:54:10.009899+00:00');
INSERT INTO public."landmark_projects" ("id","name","detail","image_url","fit","published","sort_order","created_at","updated_at") VALUES ('813ae09d-40ec-409b-b618-66b623ed2a6d','Ramky One Odyssey','Ramky One Odyssey, is a premium residential gated community located at Kokapet–Narsingi, Hyderabad. Spread across approximately 5.3 acres, the project comprises three high-rise residential towers of 3B + Ground/Stilt + 36 floors, housing around 783 units.The project has received an IGBC Gold rating and benefits from strategic connectivity to the Financial District, Gachibowli and other key commercial hubs via the ORR.','asset:odysseyCombined','contain',true,'8','2026-11-03T09:54:10.247647+00:00','2026-11-03T09:54:10.247647+00:00');
INSERT INTO public."landmark_projects" ("id","name","detail","image_url","fit","published","sort_order","created_at","updated_at") VALUES ('502aebc6-a085-4497-b6be-dde04dee39e1','Narela-Bawana waste-to-energy plant','largest waste-to-energy plant, with a capacity of 24 MW energy-generation facility spread over 100 acres','asset:narelaCombined','contain',true,'9','2026-11-03T09:54:10.485276+00:00','2026-11-03T09:54:10.485276+00:00');
-- management_people: 24 rows
INSERT INTO public."management_people" ("id","grp","slug","name","designation","image_url","sections","published","sort_order","created_at","updated_at") VALUES ('1cdae1a1-e9bc-42e7-b4db-d913aaa0d204','board','yancharla-rathnakara-nagaraja','Mr. Yancharla Rathnakara Nagaraja','Managing Director','/__l5e/assets-v1/a6828b85-e5cd-4cfa-9974-43df5023a9fa/director-yancharla-rathnakara-nagaraja.jpg','{"awards": [], "biography": ["Mr. Y R Nagaraja is a seasoned Civil Engineer with a Bachelor’s Degree from Karnataka University and over 41 years of comprehensive experience in civil, industrial and environmental infrastructure. He began his career with the Public Works Department, Government of Karnataka and later contributed his expertise at Mandanlal Steels Limited and Navega Engineers Private Limited. Over the decades, he has successfully led the design, engineering, and execution of numerous infrastructure projects across India and abroad, spanning water treatment, industrial wastewater, sewage treatment, roads, industrial buildings, and specialized structural works."], "education": [], "expertise": ["A recognized expert in environmental infrastructure, Mr. Nagaraja played a pivotal role in the development of India’s first major hazardous waste landfill facility. He was instrumental in the design and execution of two phases of Waste to Energy Plants at Jawahar Nagar, Hyderabad, and an additional plant at Dundigal. Under his leadership, his company secured and implemented the Hyderabad Waste Management Project (HWMP) on a Build-Own-Operate (BOO) basis – the first project of its kind in the country. He has also designed and commissioned wastewater and sewage treatment plants utilizing UASBR (Upflow Anaerobic Sludge Blanket Reactor) and SBR technology, reinforcing his technical versatility and innovative approach."], "otherInformation": ["Mr. Nagaraja is an active contributor to the professional community through participation in seminars, symposia, and training programs. He is a member of several prestigious institutions including the Environmental Auditors Registration Association (EARA), Indian Association for Environmental Management (IAEM), the Institution of Engineers (India), and the Institute of Public Health Engineers Association. His extensive travel within India and internationally has provided valuable exposure to global best practices in civil construction and environmental management, enhancing his ability to deliver sustainable and forward-thinking solutions."], "professionalExperience": []}'::jsonb,true,'1','2026-11-03T02:13:45.589059+00:00','2026-11-03T02:13:45.589059+00:00');
INSERT INTO public."management_people" ("id","grp","slug","name","designation","image_url","sections","published","sort_order","created_at","updated_at") VALUES ('713a8ab0-e06a-4c5f-bca6-39e821f4474d','board','anantapuram-guggela-ravindranath-reddy','Dr. Anantapuram Guggela Ravindranath Reddy','Non-Executive Director','/__l5e/assets-v1/c30c8b65-4b1e-4422-8911-d94ed914e977/director-anantapuram-guggela-ravindranath-reddy.jpg','{"awards": [], "biography": [], "education": ["Dr. A. G. Ravindranath Reddy is a Fellow Company Secretary, a Post Graduate in Commerce and a Graduate in Law. He is a Corporate Consultant for the past 29 years, specializing in corporate laws, economic laws, foreign exchange laws, corporate restructuring, etc. He believes in ‘learning beyond law’ and was awarded with a Ph.D. in Management on topic – ‘Role of Shareholders in Corporate Governance’."], "expertise": [], "otherInformation": [], "professionalExperience": ["He practiced as an Advocate in Criminal Courts for the initial 2 years of his career. Post that, he had also worked in senior management levels in various companies for 6 years. He possesses hands-on experience in legal and court proceedings, handling public issues, coordinating amalgamation proceedings, negotiating and drafting various agreements, restructuring and implementation and compliance of corporate governance."]}'::jsonb,true,'2','2026-11-03T02:13:45.589059+00:00','2026-11-03T02:13:45.589059+00:00');
INSERT INTO public."management_people" ("id","grp","slug","name","designation","image_url","sections","published","sort_order","created_at","updated_at") VALUES ('2b71cbbe-c9ed-491a-be30-88b50494ef66','board','isaac-wesley-vijaya-kumar','Mr. Isaac Wesley Vijaya Kumar','Non-Executive Director','/__l5e/assets-v1/795b329f-752d-4d90-ba53-ce7e63279dfa/director-isaac-wesley-vijaya-kumar.jpg','{"awards": [], "biography": [], "education": ["Mr. I W Vijaya Kumar is a Chartered Accountant from the Institute of Chartered Accountants of India (ICAI) and is also a Company Secretary from the Institute of Company Secretaries of India (ICSI) and is currently trained for Certified Public Accountant (CPA), New York, USA. He is also an Oracle Financial Consultant and has vast knowledge in US GAAP, UK GAAP, Indian GAAP and IFRS."], "expertise": [], "otherInformation": [], "professionalExperience": ["Mr. I W Vijaya Kumar has 31 + years of multinational experience in the areas of finance and strategic planning, business valuations, corporate accounting and Taxation, Internal and External Audit, Legal , Secretarial, general administration and management experience with expertise in project finance, accounting systems development, fiscal management, financial reporting, developing and implementing financial and operational controls.", "Mr. I W Vijaya Kumar prior to joining Ramky was the Chief Financial Officer of Doowa Group of Companies, Bangkok, Thailand. Mr. Vijaya Kumar has hands on experience heading the finance function in various industries such as infrastructure – construction & dredging, real estate, embroidery, textile manufacturing and export, IT education and training, Thai food and beverage business; Garment manufacture and export; and owning and operating hotels and serviced apartments."]}'::jsonb,true,'3','2026-11-03T02:13:45.589059+00:00','2026-11-03T02:13:45.589059+00:00');
INSERT INTO public."management_people" ("id","grp","slug","name","designation","image_url","sections","published","sort_order","created_at","updated_at") VALUES ('f6e7ab00-0856-48af-b344-521f43a64473','board','ravi-kumar-reddy-somavarapu','Dr. Ravi Kumar Reddy Somavarapu','Independent Director','/__l5e/assets-v1/a40a2341-5a3b-4e84-98da-66e74a0e2fab/director-ravi-kumar-reddy-somavarapu.jpg','{"awards": ["Beyond his corporate role, Dr. Ravi has been actively engaged in rural empowerment for over two decades through REEDS, a non-profit organisation dedicated to improving quality of life in villages. His initiatives in sanitation, water conservation, and community development have earned national recognition, including the India Today Safaigiri Award – Water Warrior (2016) and the Gramodaya Bandhu Mitra Puraskar (2020). He was also conferred an Honorary Doctorate in 2015 by American Sentinel University (now part of Post University, USA) for his contributions to rural upliftment and skills development."], "biography": ["Dr. Ravi Kumar Reddy Somavarapu, a Chartered Accountant with over 30 years of professional experience, is Managing Partner of RK Reddy & Associates, Hyderabad. He advises enterprises on financial planning, regulatory compliance, and business management, and serves as an Independent Director on several corporate boards.", "He brings to the board a unique blend of professional expertise and social commitment."], "education": [], "expertise": [], "otherInformation": [], "professionalExperience": []}'::jsonb,true,'4','2026-11-03T02:13:45.589059+00:00','2026-11-03T02:13:45.589059+00:00');
INSERT INTO public."management_people" ("id","grp","slug","name","designation","image_url","sections","published","sort_order","created_at","updated_at") VALUES ('6aba3f91-d972-4e20-b881-810d3b257b46','board','eshwar-reddy-purmandla','Mr. Eshwar Reddy Purmandla','Independent Director','/__l5e/assets-v1/b2c4832a-507a-4ea3-aef0-cb13e5a21f1c/director-eshwar-reddy-purmandla.jpg','{"awards": [], "biography": [], "education": [], "expertise": ["His specialization in various aspects of the process industry, including fertilizers, pesticides, fine chemicals, and bulk drugs gives him a broad and impactful range of expertise. His focus on safety, health, and environment, as well as effluent and sewerage systems, is crucial for sustainable industrial practices."], "otherInformation": [], "professionalExperience": ["Mr. Eshwar Reddy Purmandla holds, B.E (Hons), Chemical Engineering from Birla Institute of Technology & Science, Pilani, Rajasthan and M.Tech. (Process Plant Design) – IIT, Delhi, India, with 45 years of work experience. He has worked with Rashtriya Chemicals & Fertilizers Limited, which is the largest government owned company manufacturing Nitrogen and Nitro phosphorus based fertilizers and Industrial Chemicals in India. He worked for around 25 years in Voltas Limited and Rallis India Limited (both TATA group companies) producing agrochemicals, pharmaceuticals and fine chemicals. Handled assignments in Production, technical Services, new projects, product developments and environment protection and pollution control. Handled simultaneously multi-disciplinary teams and multiple projects at different locations."]}'::jsonb,true,'5','2026-11-03T02:13:45.589059+00:00','2026-11-03T02:13:45.589059+00:00');
INSERT INTO public."management_people" ("id","grp","slug","name","designation","image_url","sections","published","sort_order","created_at","updated_at") VALUES ('66c9dd15-35d9-4e49-a55e-7d6b9b296533','senior','ravi-prasad-polimetla','Dr. Ravi Prasad Polimetla','Head - EPC','/__l5e/assets-v1/3def8397-b69c-4097-a249-9f45247d6ee4/senior-mgmt-13.jpg','{}'::jsonb,true,'2','2026-11-03T02:13:45.589059+00:00','2026-11-03T02:13:45.589059+00:00');
INSERT INTO public."management_people" ("id","grp","slug","name","designation","image_url","sections","published","sort_order","created_at","updated_at") VALUES ('b4009e9a-3a6c-4221-a46a-2560693d3b2b','board','malvieka-joshi','Ms. Malvieka Joshi','Independent Director','/__l5e/assets-v1/cb7a327c-5b25-417e-8610-92ac1789de46/director-malvieka-joshi.jpg','{"awards": [], "biography": [], "education": ["Ms. Malvieka Joshi is a seasoned Legal and Human Resources (HR) Professional with over 30 years of diverse experience across industries such as FMCG, Telecom, and Information Technology. She is a Fellow Company Secretary (FCS) from the Institute of Company Secretaries of India (ICSI), an Associate Certified Coach (ACC) from the International Coach Federation (ICF) and holds certifications from Cornell University. She is also a BA (Hons.) graduate from St. Xavier’s College."], "expertise": ["Ms. Joshi brings deep expertise in corporate governance, HR strategy, legal compliance, organizational development, and executive coaching. She has coached senior executives for over 500 hours as an ICF-certified coach and serves as an Independent Director on the Board of Disa India Limited (Norican Group)."], "otherInformation": [], "professionalExperience": ["Over her three decade career, Ms. Joshi has held leadership roles with global organizations such as F5 Networks, Ciena India, Fibcom India, and Osram India (Siemens Group). At F5 Networks, she served as Vice President – Human Resources and played a pivotal role in setting up of state-of-the-art Engineering Centre in Hyderabad, scaling it from inception to a workforce of over 1,100 professionals. Under her leadership, F5 India was recognized among the Top 25 Companies in Asia and ranked among the Top 5 in India for millennials and women, also certified as a “Great Place to Work”.", "Earlier Ms. Joshi has joined Ciena India, as its first employee and was instrumental in building a team of more than 3,500 professionals, leading the organisation to bag multiple Workplace Excellence Awards. In the early phase of her career, she held key legal, secretarial, HR Leadership role including Company Secretary and HR Head at Fibcom India Limited, where she oversaw Statutory compliance, Board Governance, and Employee Relationship."]}'::jsonb,true,'6','2026-11-03T02:13:45.589059+00:00','2026-11-03T02:13:45.589059+00:00');
INSERT INTO public."management_people" ("id","grp","slug","name","designation","image_url","sections","published","sort_order","created_at","updated_at") VALUES ('246c3a5d-47e7-4d51-902d-0142365e8ef5','board','peddibhotla-gangadhara-sastry','Dr. Peddibhotla Gangadhara Sastry','Independent Director','/__l5e/assets-v1/fce0f600-85ed-4daa-896b-e2d05f8092e5/director-peddibhotla-gangadhara-sastry.jpg','{"awards": ["Dr. P G Sastry has received numerous prestigious International, National and State level awards throughout his illustrious career. He was awarded Germany’s esteemed Post-doctoral Humboldt Fellowship thrice in 1963, 1964, and 1970. He also received three best paper awards from the Institution of Engineers (IEI) in 1978, 1979, and 1980. In 1998, he was honoured with the Professional Expertise Award from Vishwabharathi Academy. The Chief Minister of Andhra Pradesh conferred upon him the title of “Paryavarana Praveena”. In 2005, he received the Bharat Ratna Sir M. Visveswaraya Special Award from IEI, followed by the Sir Arthur Cotton Award by Jandhyala Charitable Trust in 2006. He was also titled “Professor Par Excellence” by the Chief Minister of Andhra Pradesh. In 2007, he was awarded the “Padma Bhushan Dr. K. L. Rao Special Award” by the Government of Andhra Pradesh. Additionally, he received the “Paul Harris Fellow Award” from Rotary International Foundation in 2007, “the Engineering Educator Life Time Achievement Award” by ISTE, India in 2008, “the Rotary Vocational Excellence Award” in 2009, “the Award of Excellence in Technical Education” by Lions Club in 2013, “the Life Time Achievement Award” by the Indian Society for Hydraulics in 2015, and “the Engineering Seva Ratna Award” by the International Elders Club in 2021. In 2023, he was also honoured as the “Best Professor & Director in Environment Education” by the Ideal Teaching Awards Programme (ITAP)."], "biography": [], "education": ["Dr. P G Sastry holds a Bachelor’s Degree in Civil Engineering (Honours) and a Masters in Civil Engineering from the Indian Institute of Technology(IIT), Kharagpur as well as a Doctorate in Engineering from Technical University, Dresden, Germany and Post-Doctoral Research in Berlin and Hanover in Germany."], "expertise": [], "otherInformation": ["Dr. P G Sastry has made significant contributions to the establishment of Outcomes-Based Engineering Education (OBE). During his visiting professorship at Ohio State University, USA in 1998, he was involved in the preparations by the Accreditation Board for Engineering & Technology (ABET) for the introduction of OBE in US Engineering and Technology Institutions, which was implemented in 2000, Europe followed suit in 2010.", "In India, the National Board of Accreditation (NBA) introduced a paradigm shift in Engineering Education by transitioning to OBE in 2013. As one of the pioneers of OBE, Dr. Sastry played a crucial role in its establishment in Telangana, Andhra Pradesh, and other states. He trained 8,400 faculty members in 92 engineering colleges and polytechnics between 2010 and 2020, significantly impacting the quality of Engineering Education in India."], "professionalExperience": ["Worked formerly as a Chairman in Ministry of Environment, Forests and Climate Change, Govt. of India, for Clearing Irrigation & Hydropower Projects in India. He was a Director, NIT, Warangal and Director General, Water and Land Management Training & Research Institute, Government of Andhra Pradesh. He is a Training Specialist, World Bank Hydrology Project, also a senior Expert, Netherlands-Funded Water Supply Project. He was Chief Advisor, Environment Protection Training & Research Institute and visiting Professor, Ohio State University, USA."]}'::jsonb,true,'7','2026-11-03T02:13:45.589059+00:00','2026-11-03T02:13:45.589059+00:00');
INSERT INTO public."management_people" ("id","grp","slug","name","designation","image_url","sections","published","sort_order","created_at","updated_at") VALUES ('996907af-725c-427e-aa7c-df860fa27437','executive','sunil-s-nair','Mr. Sunil S Nair','Chief Executive Officer','/__l5e/assets-v1/595e8d6b-de95-44cc-991f-0933870d076c/sunil-s-nair.jpg','{"awards": [], "biography": ["Mr. Sunil S Nair, Chief Executive Officer, is a Chemical Engineering Graduated from Calicut University also holds a CFA certification and has completed the Advanced Management Program at INSEAD. He brings with him strong technical expertise, strategic leadership, and strong commercial acumen."], "expertise": [], "qualifications": [], "otherInformation": [], "professionalExperience": ["Mr. Sunil Nair brings with him a wealth of leadership experience, having served as Chief Executive Officer (CEO) and Managing Director (MD) across several organizations including Utico FZC, Litwin PEL, CAE, and Galfar Engineering. At Utico FZC, he led the growth of the water business from a modest local portfolio to a fully integrated developer with in-house EPC capabilities. He oversees a $200 million P&L, manages multi million in assets, and executes large-scale projects ranging from $25 million to $400 million, including BOO, EPC, and O&M contracts.", "Previously, as CEO for UAE, Oman, and Africa regions, Mr. Sunil Nair has successfully turned around the company from near bankruptcy, growing revenue from $10 million to $250 million while maintaining healthy profit margins. He has also led strategic acquisitions, organizational restructuring, and business development initiatives across multiple geographies."]}'::jsonb,true,'1','2026-11-03T02:13:45.589059+00:00','2026-11-03T02:13:45.589059+00:00');
INSERT INTO public."management_people" ("id","grp","slug","name","designation","image_url","sections","published","sort_order","created_at","updated_at") VALUES ('3874dea0-400e-4316-a391-9604178189a5','executive','sravanth-rayapudi','Mr. Sravanth Rayapudi','Chief Financial Officer','/__l5e/assets-v1/5fe981dd-ae08-4dd8-89f4-2b045fba9fba/sravanth-rayapudi.jpg','{"awards": ["Sravanth’s contributions have been recognized with the “CFO of the Year 2026– Infrastructure” award at the Great India Forum, and he is frequently invited as a thought leader and panel speaker at industry conclaves."], "biography": ["Sravanth Rayapudi is a qualified Chartered Accountant and finance strategist with over 15 years of diversified experience spanning Healthcare, Real Estate, Infrastructure, Investment Advisory, Transaction Advisory, and Corporate Finance."], "expertise": ["Across his career, Sravanth has built deep expertise in fund raising and investor relations, mergers and acquisitions, due diligence and transaction structuring, financial modeling and valuation, risk management, and corporate governance. He has led the raising, consolidation, and refinancing of debt exceeding ₹2,500 crore, bringing borrowing costs down from as high as ~16% to single digits, and has evaluated and executed acquisition and investment opportunities worth several thousand crores.", "A resilient crisis leader, he steered organizations with disciplined liquidity planning and cash flow management, helping his teams outperform industry benchmarks on financial sustainability. He is equally recognized for building best-in-class MIS, budgeting, and internal control frameworks."], "qualifications": [], "otherInformation": ["At RAMKY, he continues to spearhead strategic acquisitions, equity fundraising, and governance initiatives that support the company’s next phase of growth."], "professionalExperience": ["Prior to RAMKY, Sravanth spent over eight years as Head of Finance at GAR Infobahn (GAR Corporation Ltd), a Hyderabad-based commercial real estate operator with a 10-million-square-foot portfolio, where he drove financial transformation, scaled operations, and led large-scale fundraising initiatives. Earlier in his career, he spent seven years as Lead Finance for the Infrastructure vertical at Incor Infrastructure Pvt Ltd, a commercial and residential real estate developer, reporting directly to the Chairman and Managing Director — following an initial engagement with Omni Hospitals on the due diligence for a ₹65 crore private placement supporting its expansion."]}'::jsonb,true,'2','2026-11-03T02:13:45.589059+00:00','2026-11-03T02:13:45.589059+00:00');
