INSERT INTO public."media_items" ("id","item_type","item_date","kicker","title","summary","paragraphs","source","document_url","external_url","link_label","published","sort_order","created_at","updated_at") VALUES ('ace4ce3e-2087-4d05-80f5-ac32e6fa8103','Media Coverage',NULL,'Leadership Perspective | Featured in Forbes India','Building What Comes Next',NULL,'["Ramky Infrastructure Limited''s vision for the future takes centre stage in this featured article published by Forbes India, highlighting the leadership perspective of our CEO and the company''s journey in shaping the next chapter of infrastructure development.", "With a focus on the future of infrastructure, this feature offers an opportunity to explore Ramky''s leadership vision, evolving priorities, and commitment to delivering infrastructure that creates lasting value."]'::jsonb,'Forbes India',NULL,'https://www.forbesindia.com/article/upfront/brand-connect/ramky-infrastructure-limited-building-what-comes-next/2999365/1','Read the full article',true,'1','2026-11-03T03:31:37.17592+00:00','2026-11-03T03:31:37.17592+00:00');
